describe("Gem quality planning",function()
 local planner=require("Modules.GemQualityPlan")
 local gem="Item Class: Active Skill Gems\nRarity: Gem\nArc\n--------\nLevel: 20 (Max)\nQuality: +12% (augmented)"
 it("plans prisms for copied active and support gems",function()
  local result=planner.inspect(gem,20);assert.equal("available",result.status);assert.equal(8,result.prisms);assert.equal(20,result.level);assert.equal("gems",result.milestoneDraft.kind);assert.matches("8 Gemcutter",result.milestoneDraft.notes)
  assert.is_true(result.corruption.vaalOrb.available);assert.is_false(result.corruption.lapidaryLens.available)
  assert.equal(2,result.corruption.historicalQualityRange.min);assert.equal(22,result.corruption.historicalQualityRange.max)
  assert.equal(19,result.corruption.historicalLevelRange.min);assert.equal(21,result.corruption.historicalLevelRange.max)
  assert.equal("Vaal Arc",result.corruption.vaalCandidates[1])
  local support="Item Class: Support Skill Gems\nRarity: Gem\nAdded Fire Damage Support\n--------\nLevel: 5"
  result=planner.inspect(support,10);assert.is_true(result.support);assert.equal(10,result.prisms)
  result=planner.inspect(gem,10);assert.equal("complete",result.status);assert.equal(0,result.prisms)
 end)
 it("compares the support gem vendor recipe without hiding the level reset",function()
  local support="Item Class: Support Skill Gems\nRarity: Gem\nAdded Fire Damage Support\n--------\nLevel: 20 (Max)\nQuality: +4%"
  local result=planner.inspect(support,20);assert.equal(16,result.prisms);assert.is_true(result.vendorRecipe.available);assert.equal(1,result.vendorRecipe.prisms);assert.equal(1,result.vendorRecipe.outputLevel);assert.equal(20,result.vendorRecipe.outputQuality)
  assert.matches("level it again",result.vendorMilestoneDraft.notes);assert.is_false(planner.inspect(support.."\nCorrupted",20).vendorRecipe.available)
  assert.is_false(planner.inspect(support:gsub("Level: 20","Level: 19"),20).vendorRecipe.available)
  assert.is_false(planner.inspect(gem,20).vendorRecipe.available)
  local awakened=support:gsub("Added Fire Damage Support","Awakened Added Fire Damage Support");assert.is_false(planner.inspect(awakened,20).vendorRecipe.available)
  local exceptional=support:gsub("Added Fire Damage Support","Empower Support");assert.is_false(planner.inspect(exceptional,20).vendorRecipe.available)
 end)
 it("explains limits and rejects inconsistent input",function()
  local result=planner.inspect(gem.."\nCorrupted",20);assert.equal("unavailable",result.status);assert.matches("corrupted",result.reason);assert.is_false(result.corruption.vaalOrb.available);assert.is_true(result.corruption.lapidaryLens.available)
  result=planner.inspect(gem,23);assert.equal("unavailable",result.status);assert.matches("20%%",result.reason)
  local capped=planner.inspect(gem:gsub("+12%%","+20%%"),20);assert.equal(10,capped.corruption.historicalQualityRange.min);assert.equal(23,capped.corruption.historicalQualityRange.max)
  local legacy=planner.inspect(gem:gsub("+12%%","+30%%"),30);assert.is_nil(legacy.corruption.historicalQualityRange)

  result=planner.inspect(gem:gsub("\nArc\n","\nVaal Arc\n"),20);assert.is_true(result.corrupted);assert.equal("unavailable",result.status)
  result=planner.inspect(gem.."\nTwice Corrupted",12);assert.is_true(result.twiceCorrupted);assert.equal("complete",result.status);assert.is_false(result.corruption.lapidaryLens.available)
  assert.has_error(function() planner.inspect(gem:gsub("Active Skill Gems","Support Skill Gems"),20) end)
  assert.has_error(function() planner.inspect(gem:gsub("Arc","Unknown Gem"),20) end)
  assert.has_error(function() planner.inspect(gem.."\nQuality: +3%",20) end)
  assert.has_error(function() planner.inspect(gem,101) end)
 end)
 it("lets a user paste a gem and inspect or copy a guide",function()
  newBuild();main.popups={};local panel=require("Classes.GemQualityPlanControl");panel.Open(build)
  local c=main.popups[1].controls;local environment=getfenv(panel.Open);local original=environment.Paste
  environment.Paste=function() return gem end;local ok,err=pcall(function() c.paste:Click() end);environment.Paste=original;assert.is_true(ok,tostring(err))
  assert.is_true(c.copy:IsEnabled());local text="";for _,line in ipairs(c.result.list) do text=text..(line[1] or "") end;assert.matches("8 Gemcutter",text)
  assert.is_true(c.keep:IsEnabled());c.keep:Click();assert.is_false(c.keep:IsEnabled());assert.equal(1,#build.savers.BuildJourney.data.milestones)
  local saved=build.savers.BuildJourney.data.milestones[1];assert.equal("gems",saved.kind);assert.matches("8 Gemcutter",saved.notes)
  local xml={};build.savers.BuildJourney:Save(xml);local reopened=require("Modules.BuildJourney").new(build);reopened:Load(xml);assert.equal(saved.notes,reopened.data.milestones[1].notes)
  environment.Paste=function() return (gem:gsub("Level: 20","Level: 19")) end;ok,err=pcall(function() c.paste:Click() end);environment.Paste=original;assert.is_true(ok,tostring(err));assert.is_true(c.keep:IsEnabled())

  c.target:SetText("23",true);text="";for _,line in ipairs(c.result.list) do text=text..(line[1] or "") end;assert.matches("20%%",text);main.popups={}
 end)
end)
